import json
B = {"customer_id": "c1", "title": "Mr", "last_name": "Reyes"}
def acct(now, days, typ="credit_card"):
    v = dict(B, now=now, st="account", pending="get_account", a_ok="true", p0_product_id="p1", p0_type=typ, p0_past_due=300, p0_days_late=days)
    if typ == "credit_card": v.update(p0_card_last4="4821", p0_minimum_payment=50)
    else: v["p0_instalment_amount"] = 120
    return v
def pay(now, band="late", **kw):
    v = dict(B, now=now, st="pay", pay_q="today", full=300, floor=50, product_id="p1", prod_words="credit card ending 4821",
             attempts_allowed=2 if band == "late" else 1, attempts_used=0, pending="none")
    v["deadline"] = kw.pop("deadline")
    v.update(kw); return v
S = []
def sc(name, run, vars, expect): S.append({"name": name, "run": run, "vars": vars, "expect": expect})
sc("opening", ["init"], dict(B, now="2026-10-14T11:00"), {"say": {"contains": "We are recording this call. Am I speaking with Mr Reyes?"}, "st": "who"})
sc("late band deadline Wed (holiday 20th skipped)", ["step"], acct("2026-10-14T11:00", 14), {"deadline": "2026-10-22", "band": "late", "attempts_allowed": 2, "floor": 50.0, "say": {"contains": "credit card ending 4821"}})
sc("early band deadline", ["step"], acct("2026-10-14T11:00", 3), {"deadline": "2026-10-29", "band": "early", "attempts_allowed": 1})
sc("band edge 7 early", ["step"], acct("2026-10-14T11:00", 7), {"band": "early"})
sc("band edge 8 late, loan floor", ["step"], acct("2026-10-14T11:00", 8, "car_loan"), {"band": "late", "floor": 120.0, "say": {"contains": "car loan"}})
sc("late deadline from Friday", ["step"], acct("2026-10-16T10:00", 20), {"deadline": "2026-10-26"})
sc("deadline day before holiday", ["step"], acct("2026-10-19T10:00", 20), {"deadline": "2026-10-27"})
