sc("next friday on friday = following week", ["step"], pay("2026-10-16T10:00", deadline="2026-10-26", date_words="next Friday"), {"c_date": "2026-10-23"})
sc("next friday early band", ["step"], pay("2026-10-16T10:00", band="early", deadline="2026-10-30", date_words="next Friday"), {"c_date": "2026-10-23", "st": "confirm"})
sc("this friday", ["step"], pay("2026-10-14T11:00", deadline="2026-10-22", date_words="this Friday"), {"c_date": "2026-10-16"})
sc("refusal attempt 1 last bd of week", ["step"], pay("2026-10-14T11:00", deadline="2026-10-22", answer="no"), {"o_date": "2026-10-16", "o_amount": 300.0, "attempts_used": 1})
sc("refusal attempt 1 on friday -> next week", ["step"], pay("2026-10-16T10:00", deadline="2026-10-26", answer="no"), {"o_date": "2026-10-23"})
