sc("attempts exhausted late", ["step"], pay("2026-10-14T11:00", deadline="2026-10-22", answer="no", attempts_used=2, pay_q="offer"), {"outcome": "no_promise", "reason": "refused"})
sc("early band one attempt", ["step"], pay("2026-10-14T11:00", band="early", deadline="2026-10-29", answer="no", attempts_used=1, pay_q="offer"), {"outcome": "no_promise", "reason": "refused"})
sc("too much -> floor once", ["step"], pay("2026-10-14T11:00", deadline="2026-10-22", intent="too_much"), {"o_amount": 50.0, "floor_offered": "yes", "say": {"contains": "rest stays overdue"}})
