sc("promise ok -> close promise", ["step"], pay("2026-10-14T11:00", deadline="2026-10-22", st="confirm", pending="create_promise", pr_ok="true"), {"outcome": "promise", "bye": {"contains": "You will receive a text message confirming this promise."}})
sc("promise fail twice", ["step", "step"], pay("2026-10-14T11:00", deadline="2026-10-22", st="confirm", pending="create_promise", pr_ok="none"), {"outcome": "no_promise", "reason": "service_error"})
sc("transfer after promise", ["step"], pay("2026-10-14T11:00", deadline="2026-10-22", promised="yes", pending="transfer_to_agent", tr_ok="true", t_key="t_human"), {"outcome": "transferred", "reason": "human"})
# opening / third party
sc("confirmed -> dob", ["step"], dict(B, now="2026-10-14T11:00", st="who", who="confirmed"), {"st": "dob"})
sc("no + question -> third party", ["step"], dict(B, now="2026-10-14T11:00", st="who", who="not_customer", question="purpose"), {"st": "third", "say": {"contains": "When can Mr Reyes be reached?"}})
sc("unclear twice -> unclear", ["step", "step"], dict(B, now="2026-10-14T11:00", st="who", who="unclear", who_asks=1), {"outcome": "not_reached", "reason": "unclear"})
sc("deceased", ["step"], dict(B, now="2026-10-14T11:00", st="third", intent="deceased"), {"reason": "deceased", "bye": {"contains": "I am sorry for your loss."}})
